  `nhom` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0 thuong, 1 huyen thoai, 2 huyen ao, 3 Ultra Beast, 4 Nghich ly',
  `ho` smallint(6) NOT NULL DEFAULT 0 COMMENT 'evolution_chain_id PokeAPI',
  `dex_goc` smallint(6) NOT NULL DEFAULT 0 COMMENT 'loai goc cua ho (Keo dung chung ca ho)',
