  `can_nang` smallint(6) NOT NULL DEFAULT 0 COMMENT 'hg',
  `dot_mo` tinyint(4) NOT NULL DEFAULT 4 COMMENT '1 A Gen1-2, 2 B Gen3, 3 C Gen4, 4 D Gen5-9',
  `bat` tinyint(4) NOT NULL DEFAULT 0 COMMENT '1 = loai da mo (ngoai troi, bat duoc)',
  `mo_ta` varchar(255) NOT NULL DEFAULT '',
