-- ---------------------------------------------------------------- 1. cot tob_char.o_mo_rong (idempotent)
ALTER TABLE `tob_char` ADD COLUMN IF NOT EXISTS `o_mo_rong` INT NOT NULL DEFAULT 0 COMMENT 'O hanh trang le: ve mo rong / mua xu (real.MoRongTuiGame)';

