  `cap_max` TINYINT NOT NULL,
  `trong_so` SMALLINT NOT NULL,
  `bac_gap` TINYINT NOT NULL,
  PRIMARY KEY (`chu_ky`, `nhom`, `dex`, `vung`),
  KEY `k_ky_vung` (`chu_ky`, `nhom`, `vung`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

