-- Nhom trung: CUNG luoc do nhanh ket-doi (sql/sua_ket_doi.sql). id = egg_group PokeAPI. Khong ghi de dong da co.
CREATE TABLE IF NOT EXISTS `data_nhom_trung_ten` (
  `id` TINYINT UNSIGNED NOT NULL,
  `ma` VARCHAR(20) NOT NULL,
  `ten` VARCHAR(50) NOT NULL,
  `ket_doi_duoc` TINYINT NOT NULL DEFAULT 1,
  `sua_luc` DATETIME DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `data_nhom_trung` (
  `dex` SMALLINT UNSIGNED NOT NULL,
  `ten_loai` VARCHAR(30) NOT NULL,
  `nhom1` TINYINT UNSIGNED NOT NULL,
  `nhom2` TINYINT UNSIGNED DEFAULT NULL,
  `sua_luc` DATETIME DEFAULT NULL,
  PRIMARY KEY (`dex`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


-- Thu phuc: CUNG luoc do nhanh bat-trade (data_bat_loai, data_bat_chi_so_loai). Chi them dong cho loai DA MO;
-- dong da co giu nguyen (ti_le_phan_nghin chi dat khi dang 0 = theo bac cu). do_hiem: T1 -> 0, T2 -> 1, T3 -> 2, T4-T5 -> 3.
CREATE TABLE IF NOT EXISTS `data_bat_loai` (
  `dex` SMALLINT NOT NULL,
  `ten` VARCHAR(32) NOT NULL DEFAULT '',
  `do_hiem` TINYINT NOT NULL DEFAULT 0,
  `ti_le_phan_nghin` SMALLINT NOT NULL DEFAULT 0,
  `tien_hoa_thanh` SMALLINT NOT NULL DEFAULT 0,
  `cap_tien_hoa` TINYINT NOT NULL DEFAULT 0,
  `keo_tien_hoa` SMALLINT NOT NULL DEFAULT 0,
  `bat_duoc` TINYINT NOT NULL DEFAULT 1,
  `chi_su_kien` TINYINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`dex`)
) DEFAULT CHARSET=utf8;
ALTER TABLE `data_bat_loai` ADD COLUMN IF NOT EXISTS `tien_hoa_trao_doi` TINYINT NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS `data_bat_chi_so_loai` (
  `dex` SMALLINT NOT NULL,
  `hp` SMALLINT NOT NULL DEFAULT 60,
  `tan_cong` SMALLINT NOT NULL DEFAULT 60,
  `phong_thu` SMALLINT NOT NULL DEFAULT 60,
  `tan_cong_db` SMALLINT NOT NULL DEFAULT 60,
  `phong_thu_db` SMALLINT NOT NULL DEFAULT 60,
  `toc_do` SMALLINT NOT NULL DEFAULT 60,
  PRIMARY KEY (`dex`)
) DEFAULT CHARSET=utf8;

ON DUPLICATE KEY UPDATE `ti_le_phan_nghin` = IF(`ti_le_phan_nghin` = 0, VALUES(`ti_le_phan_nghin`), `ti_le_phan_nghin`);
ON DUPLICATE KEY UPDATE `ti_le_phan_nghin` = IF(`ti_le_phan_nghin` = 0, VALUES(`ti_le_phan_nghin`), `ti_le_phan_nghin`);
ON DUPLICATE KEY UPDATE `ti_le_phan_nghin` = IF(`ti_le_phan_nghin` = 0, VALUES(`ti_le_phan_nghin`), `ti_le_phan_nghin`);
ON DUPLICATE KEY UPDATE `ti_le_phan_nghin` = IF(`ti_le_phan_nghin` = 0, VALUES(`ti_le_phan_nghin`), `ti_le_phan_nghin`);
ON DUPLICATE KEY UPDATE `ti_le_phan_nghin` = IF(`ti_le_phan_nghin` = 0, VALUES(`ti_le_phan_nghin`), `ti_le_phan_nghin`);

-- Het tep. Kiem du lieu: server/test/KiemDuLieuLoai (doc thang tep nay).
-- >>> them_loai_bo_sung.sql
-- =====================================================================================================================
-- HTBB - BO SUNG 1.025 LOAI (loai-bo-sung): mo ta Pokedex tieng Viet, ban sac mau (shiny), neo phu kien goi tai.
-- TEP SINH (dung sua tay): python3 -I tools/pokemon/loai/sinh_bo_sung_loai.py tu tools/pokemon/loai/mo_ta_loai.json
--   (mo ta TU VIET tu su kien he / noi song / dac diem / tien hoa, khong chep Pokedex chinh thuc) va server/map/loai
--   (<NNNN>.goi + <NNNN>s.goi: PMDCollab SpriteCollab 4702f10d888d19e804c5986a91170dfc92ae01b8, CC BY-NC 4.0).
-- Idempotent, MariaDB 10.3+, utf8. Chay SAU khoi them_loai_day_du.sql. mo_ta chi ghi o dong dang rong (giu mo ta
-- nguoi van hanh da sua tren web). Kiem: server/test/KiemLoaiBoSung.
--   data_loai_sprite.shiny            1 = co goi ban sac mau <NNNN>s.goi (loai do moi duoc tung shiny ngoai troi)
--   data_loai_sprite.neo              1 = goi co khoi neo phu kien PMD (trang phuc / the ban dong hanh tren loai tai)
-- =====================================================================================================================

ALTER TABLE `data_loai_sprite`
  ADD COLUMN IF NOT EXISTS `shiny` TINYINT NOT NULL DEFAULT 0 COMMENT '1 = co goi ban sac mau server/map/loai/<NNNN>s.goi',
  ADD COLUMN IF NOT EXISTS `kich_thuoc_shiny` INT NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `ghi_cong_shiny` VARCHAR(255) NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `neo` TINYINT NOT NULL DEFAULT 0 COMMENT '1 = goi co khoi neo phu kien PMD',
  ADD COLUMN IF NOT EXISTS `ban_nhap` TINYINT NOT NULL DEFAULT 0 COMMENT '1 = sprite PMDCollab chua hoan thien',
  ADD COLUMN IF NOT EXISTS `nguon_sprite` VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'ban nhap / dang khac: nhanh PMDCollab';

DROP TEMPORARY TABLE IF EXISTS `tam_loai_sprite_bo_sung`;
CREATE TEMPORARY TABLE `tam_loai_sprite_bo_sung` (`dex` SMALLINT NOT NULL PRIMARY KEY, `shiny` TINYINT NOT NULL, `kich_thuoc` INT NOT NULL, `kich_thuoc_shiny` INT NOT NULL, `neo` TINYINT NOT NULL, `ghi_cong_shiny` VARCHAR(255) NOT NULL) ENGINE=MEMORY DEFAULT CHARSET=utf8;
UPDATE `data_loai_sprite` s JOIN `tam_loai_sprite_bo_sung` t ON t.`dex` = s.`dex`
  SET s.`shiny` = t.`shiny`, s.`kich_thuoc` = t.`kich_thuoc`, s.`kich_thuoc_shiny` = t.`kich_thuoc_shiny`,
      s.`neo` = t.`neo`, s.`ghi_cong_shiny` = t.`ghi_cong_shiny`;
DROP TEMPORARY TABLE IF EXISTS `tam_loai_sprite_bo_sung`;
