-- Het khoi them_loai_bo_sung.sql (1025 mo ta, 1025 goi, 981 goi shiny).
-- >>> them_do_trang_phuc.sql
-- ============================================================================================================
-- them_do_trang_phuc.sql (0.9.8) - SINH BOI tools/do_trang_phuc/sinh.py, dung sua tay. Idempotent, MariaDB 10.3.
--
-- 1) Do ho moi: 628 mon data_item id 1400..2027 (BAN SAO chi so mon goc cung o + bac; ten, icon 15000+n rieng):
--    18 bo he x 6 o x 5 bac + 3 bo vung (huy chuong Gym) x 11 bac x 8 o. Thuong bo nam TRONG tran chung.
--    Khong nguon vao moi: do ho THAY mon goc khi roi (quai / boss / che tao), real.DoMoiGame.
-- 2) Trang tri: data_trang_phuc_o (ngan sach theo o, phan nghin), data_trang_phuc (69 mon), cua hang luong
--    (nap_cua_hang, chi HINH - cung ngan sach o voi mon mien phi), tob_trang_phuc (dong chi so / bo dem).
--    So huu dung chung nap_so_huu (Tu do trang tri), mon dang mac = dang_dung.
-- Khoi nay nam trong sql/htbb.sql phan B muc 11 (sinh.py ghi thang khoi). Chay lai duoc: chi ghi de cot cua chinh khoi nay.
-- ============================================================================================================

CREATE TABLE IF NOT EXISTS `data_trang_bi_ho` (
  `ma` VARCHAR(24) NOT NULL,
  `ten` VARCHAR(64) NOT NULL DEFAULT '',
  `loai` VARCHAR(8) NOT NULL DEFAULT 'he' COMMENT 'he = bo he (6 o vai) | vung = bo huy chuong vung',
  `he` TINYINT NOT NULL DEFAULT -1 COMMENT 'he 0..17 (HePokemon), -1 = bo vung',
  `he_khac` TINYINT NOT NULL DEFAULT -1 COMMENT 'he danh sieu hieu qua vao he nay (thuong khang 4 mon)',
  `vung` VARCHAR(8) NOT NULL DEFAULT '',
  `bac_tu` TINYINT NOT NULL DEFAULT 0,
  `bac_den` TINYINT NOT NULL DEFAULT 10,
  `mo_ta` VARCHAR(255) NOT NULL DEFAULT '',
  `thu_tu` INT NOT NULL DEFAULT 0,
  `bat` TINYINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`ma`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

ON DUPLICATE KEY UPDATE `ten`=VALUES(`ten`),`loai`=VALUES(`loai`),`he`=VALUES(`he`),`he_khac`=VALUES(`he_khac`),`vung`=VALUES(`vung`),`bac_tu`=VALUES(`bac_tu`),`bac_den`=VALUES(`bac_den`),`mo_ta`=VALUES(`mo_ta`),`thu_tu`=VALUES(`thu_tu`);

CREATE TABLE IF NOT EXISTS `data_trang_bi_ho_thuong` (
  `ma_ho` VARCHAR(24) NOT NULL,
  `so_mon` TINYINT NOT NULL,
  `chi_so` VARCHAR(16) NOT NULL COMMENT 'st_he | khang_he_khac | hp | tan_cong | chi_mang',
  `phan_nghin` INT NOT NULL DEFAULT 0,
  `mo_ta` VARCHAR(128) NOT NULL DEFAULT '',
  PRIMARY KEY (`ma_ho`,`so_mon`,`chi_so`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

ON DUPLICATE KEY UPDATE `phan_nghin`=VALUES(`phan_nghin`),`mo_ta`=VALUES(`mo_ta`);

CREATE TABLE IF NOT EXISTS `data_trang_bi_moi` (
  `id_item` INT NOT NULL,
  `ma_ho` VARCHAR(24) NOT NULL,
  `type` TINYINT NOT NULL,
  `bac` TINYINT NOT NULL,
  `id_goc` INT NOT NULL COMMENT 'mon goc cung o + bac (chi so ban sao)',
  `ten` VARCHAR(64) NOT NULL DEFAULT '',
  `icon` INT NOT NULL DEFAULT 0,
  `nguon` VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'quai_he | quai_vung | boss | che_tao | gym',
  PRIMARY KEY (`id_item`),
  KEY `idx_dtbm_goc` (`type`,`bac`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

ON DUPLICATE KEY UPDATE `ma_ho`=VALUES(`ma_ho`),`type`=VALUES(`type`),`bac`=VALUES(`bac`),`id_goc`=VALUES(`id_goc`),`ten`=VALUES(`ten`),`icon`=VALUES(`icon`),`nguon`=VALUES(`nguon`);

-- data_item: ban sao cot cua mon goc (phan A sql/htbb.sql) - doi id, name, namein, xstart (icon 15000+n).
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`type`=VALUES(`type`),`style`=VALUES(`style`),`he`=VALUES(`he`),`gender`=VALUES(`gender`),`level`=VALUES(`level`),`durable`=VALUES(`durable`),`atb0`=VALUES(`atb0`),`atb1`=VALUES(`atb1`),`atb2`=VALUES(`atb2`),`atb3`=VALUES(`atb3`),`atb4`=VALUES(`atb4`),`atb5`=VALUES(`atb5`),`atb6`=VALUES(`atb6`),`atb7`=VALUES(`atb7`),`atb8`=VALUES(`atb8`),`atb9`=VALUES(`atb9`),`price`=VALUES(`price`),`clazz`=VALUES(`clazz`),`xstart`=VALUES(`xstart`),`ystart`=VALUES(`ystart`),`colortype`=VALUES(`colortype`),`nloan`=VALUES(`nloan`),`idUpLevel`=VALUES(`idUpLevel`),`namein`=VALUES(`namein`),`ideff`=VALUES(`ideff`),`pricecu`=VALUES(`pricecu`);

CREATE TABLE IF NOT EXISTS `data_trang_phuc_o` (
  `o` VARCHAR(16) NOT NULL,
  `ten` VARCHAR(32) NOT NULL DEFAULT '',
  `phan_nghin` INT NOT NULL DEFAULT 0 COMMENT 'ngan sach o (10 = 1%), mon nao dang mac cung chi dung bang nay',
  `dong` VARCHAR(80) NOT NULL DEFAULT '' COMMENT 'dong chi so chon duoc o Tu do: ma:ten,...',
  `thu_tu` INT NOT NULL DEFAULT 0,
  PRIMARY KEY (`o`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

ON DUPLICATE KEY UPDATE `ten`=VALUES(`ten`),`dong`=VALUES(`dong`),`thu_tu`=VALUES(`thu_tu`);
-- phan_nghin KHONG ghi de khi chay lai (chu game chinh tren DB); server kep cung theo tran trong ma.

CREATE TABLE IF NOT EXISTS `data_trang_phuc` (
  `ma` VARCHAR(40) NOT NULL COMMENT 'trung nap_so_huu.ma / nap_cua_hang.ma',
  `o` VARCHAR(16) NOT NULL,
  `so` TINYINT UNSIGNED NOT NULL COMMENT 'so hieu trong o (goi -102 / atlas client)',
  `ten` VARCHAR(64) NOT NULL DEFAULT '',
  `do_hiem` TINYINT NOT NULL DEFAULT 0,
  `icon` INT NOT NULL DEFAULT 0,
  `manh` VARCHAR(32) NOT NULL DEFAULT '' COMMENT 'id manh hinh (atlas)',
  `nguon` VARCHAR(16) NOT NULL DEFAULT '' COMMENT 'mien_phi | su_kien | thanh_tuu | cua_hang | che_tao',
  `tham_so` VARCHAR(96) NOT NULL DEFAULT '',
  `gia_luong` INT NOT NULL DEFAULT 0,
  `mo_ta` VARCHAR(255) NOT NULL DEFAULT '',
  `thu_tu` INT NOT NULL DEFAULT 0,
  `bat` TINYINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`ma`),
  UNIQUE KEY `uq_dtp_o_so` (`o`,`so`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

ON DUPLICATE KEY UPDATE `o`=VALUES(`o`),`so`=VALUES(`so`),`ten`=VALUES(`ten`),`do_hiem`=VALUES(`do_hiem`),`icon`=VALUES(`icon`),`manh`=VALUES(`manh`),`nguon`=VALUES(`nguon`),`tham_so`=VALUES(`tham_so`),`gia_luong`=VALUES(`gia_luong`),`mo_ta`=VALUES(`mo_ta`),`thu_tu`=VALUES(`thu_tu`);

CREATE TABLE IF NOT EXISTS `tob_trang_phuc` (
  `char_id` INT NOT NULL,
  `khoa` VARCHAR(48) NOT NULL COMMENT 'dong:<o> = ma dong chi so | sk:<ma>:<nam> = dem quai su kien',
  `gia_tri` VARCHAR(48) NOT NULL DEFAULT '',
  `luc` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`char_id`,`khoa`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- Cua hang luong (Tu do trang tri, nap_cua_hang): chi mon nguon cua_hang. co_chi_so = 0: chi so thuoc O (nhu mon mien phi)
-- (cung so voi mon mien phi), khong giao dich (giao_dich_duoc = 0) de giu gia tri khoe va khong rua xu.
CREATE TABLE IF NOT EXISTS `nap_cua_hang` (
  `ma` varchar(40) NOT NULL,
  `ten` varchar(100) NOT NULL,
  `nhom` varchar(20) NOT NULL,
  `trao` varchar(20) NOT NULL,
  `gia_luong` int NOT NULL,
  `han_ngay` int NOT NULL DEFAULT 0,
  `gioi_han` int NOT NULL DEFAULT 0,
  `nhom_xoay` int NOT NULL DEFAULT 0,
  `giao_dich_duoc` tinyint NOT NULL DEFAULT 0,
  `co_chi_so` tinyint NOT NULL DEFAULT 0,
  `dang_ban` tinyint NOT NULL DEFAULT 1,
  `thu_tu` int NOT NULL DEFAULT 0,
  `mo_ta` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`ma`)
) DEFAULT CHARSET=utf8;

-- >>> sua_tuyen_nhiem_vu.sql
-- =====================================================================================================================
--  SUA TUYEN NHIEM VU (nhanh sua-tuyen, server-only, client 0.9.7 tro len)
-- =====================================================================================================================
--
--  Khoi trong sql/htbb.sql phan B muc 11 (sau khoi them_huong_dan_tan_thu.sql). Chay lai nhieu lan van an toan (MariaDB 10.3, utf8).
--  Doi xong khoi dong lai server game (bang nhiem vu / vung dich nap luc khoi dong).
--
--  1. Lang khoi dau theo vung: bang tob_lang_khoi_dau (server ghi khi tao nhan vat moi: Kanto -> Pewter, Johto ->
--     Blackthorn). Nhan vat cu khong co dong -> giu lang dang song (khong ai bi doi cho). Server cung tu tao bang.
--  2. Buoc nhiem vu dia diem: bang data_nhiem_vu_khu_vuc - vung dich (ban do nap + khung o, nhieu dong = vao dong nao cung
--     duoc) cua moi buoc "Đứng tại điểm đánh dấu..." / "Đến ...". Chuoi chinh / phu (-64, real.KhuVucNhiemVuGame): nghe
--     NPC = nhan buoc, chi xong khi dung trong vung (noi_chuyen_sau = 1: toi roi noi chuyen moi xong). Nhiem vu So tay
--     (NhiemVuEngine) dung chung vung. bat = 0: ban do khong toi duoc -> buoc giu nhu cu (ghi_chu = ly do).
--     O dich khong di duoc / khong toi duoc tu cong da doi sang o di duoc gan nhat (va sua "(ô x,y)" trong chu).
--  3. Chu phan thuong: data_quest_moi.infogift noi len varchar(1000) (cu 200: 14 dong bi cat giua chu) va doan sau
--     "Phần thưởng:|" viet lai tu chinh dong thuong (exp, xu, luong, luong khoa, vat pham, thuoc, thuong_khac phat that) -
--     bo huy hieu (nhan khi thang Gym) / trang truyen / trang tri (chi ghi nhat ky). Moi lenh chi ghi khi cot thuong con
--     dung gia tri luc sinh. Server cung sinh lai doan nay luc gui -64 (real.ChuThuongNhiemVuGame).
--
--  Khoi SINH TU DONG: tools/pokemon/sinh_sua_tuyen.py (doc CSDL + server/cMap + bang cong RealController / BanDoHoenn).
--  Kiem: server/test/KiemSuaTuyen (doc tep nay), bot tools/pokemon/kiem_tai/KichBanSuaTuyen.java (st_*).
-- ---------------------------------------------------------------------------------------------------------------------

-- 1. Lang khoi dau ------------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `tob_lang_khoi_dau` (
  `id_char` int(11) NOT NULL,
  `vung` tinyint(4) NOT NULL,
  `lang` int(11) NOT NULL,
  `tao_luc` datetime NOT NULL,
  PRIMARY KEY (`id_char`)
) DEFAULT CHARSET=utf8;

-- 2. Vung dich buoc dia diem --------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `data_nhiem_vu_khu_vuc` (
  `ma` varchar(32) NOT NULL,
  `stt` int(11) NOT NULL DEFAULT 0,
  `map_id` int(11) NOT NULL,
  `x1` int(11) NOT NULL,
  `y1` int(11) NOT NULL,
  `x2` int(11) NOT NULL,
  `y2` int(11) NOT NULL,
  `noi_chuyen_sau` tinyint(4) NOT NULL DEFAULT 0,
  `bat` tinyint(4) NOT NULL DEFAULT 1,
  `ten_noi` varchar(128) NOT NULL DEFAULT '',
  `ghi_chu` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`ma`, `stt`)
) DEFAULT CHARSET=utf8;

-- 3. Cot chu phan thuong (200 -> 1000) ---------------------------------------------------------------------------------
ALTER TABLE `data_quest_moi` MODIFY `infogift` varchar(1000) DEFAULT NULL;

-- 4. Chuong 1 (viet tay): C01.5 / C02.4 la buoc dia diem that (loi Chansey / Kecleon: "ra dung cho do", loi xong:
--    "ban dung giua vong co chay xem") - huong dan tan thu da doi chu thanh "Nghe ... ke", nay chu noi dung viec phai lam.
UPDATE `data_quest_moi` SET `scontent` = 'Ra đồng cỏ Pallet, đứng đúng chỗ ngôi sao rơi',
  `infogift` = REPLACE(`infogift`, 'Nhiệm vụ:|Nghe Chansey kể về nơi ngôi sao rơi|Địa điểm:|Làng khởi đầu|',
    'Nhiệm vụ:|Đứng tại chỗ ngôi sao rơi trên đồng cỏ Pallet (ô 53,19)|Địa điểm:|Pallet|')
  WHERE `id` = 1005 AND `mainsub` = 0;
UPDATE `data_quest_moi` SET `scontent` = 'Ra bãi cỏ phía bắc Pallet, đứng chờ kẻ giả mạo',
  `infogift` = REPLACE(`infogift`, 'Nhiệm vụ:|Nghe Kecleon bày cách phục kích|Địa điểm:|Làng khởi đầu|',
    'Nhiệm vụ:|Đứng chờ ở bãi cỏ Pallet (ô 53,19)|Địa điểm:|Pallet|')
  WHERE `id` = 1010 AND `mainsub` = 0;

