-- >>> them_dau_truong.sql
-- =====================================================================================================================
--  DAU TRUONG BAO BOI 3v3 (de xuat D12, he_thong_day_du.md 3.6). Chay lai duoc (MariaDB 10.3, utf8).
--  Che do TACH khoi MMO: doi 3 con tu Hop PC, chuan hoa cap 50, may chu mo phong tran theo luot (real.DauTruongGame,
--  com.htbb.pokemon.DauTruongTran); diem mua rieng (khong dung Elo PvP xep hang); thuong = luong khoa tran 25 / tuan + danh
--  hieu mua co han, KHONG xu. Goi -109 (client >= 908). Test: server/test/KiemDauTruong, client_pc/test/KiemDauTruong, bot
--  tools/pokemon/kiem_tai/KichBanDauTruong.java. Web: /dau-truong (bang tuan + mua), /cam-nang/dau-truong.
--   tob_dau_truong_doi     doi tan cong / phong thu (id Hop PC) + danh tinh chong nick phu lan cuoi (tai khoan / thiet bi / IP)
--   tob_dau_truong_mua     diem mua (mua = mua PvP 13 tuan), thang / thua tan cong, thang / thua phong thu
--   tob_dau_truong_tran    moi tran: luot tinh luc bat dau, hat ngau nhien + hanh dong (phat lai), diem truoc / sau, luong
--   tob_dau_truong_thuong  thuong cuoi mua da phat (khoa mua, id_char: khong phat hai lan)
--   data_danh_hieu 9870..9878  danh hieu mua theo hang (quan quan / tinh anh / dau thu) + theo bac (Dong .. Huyen thoai), giu
--                       mot mua = 131040 phut, chi so trong ngan sach o danh hieu 1%
-- =====================================================================================================================
CREATE TABLE IF NOT EXISTS `tob_dau_truong_doi` (
  `id_char` INT NOT NULL,
  `ten` VARCHAR(32) NOT NULL DEFAULT '',
  `user_id` INT NOT NULL DEFAULT 0,
  `may` VARCHAR(64) NOT NULL DEFAULT '',
  `ip` VARCHAR(45) NOT NULL DEFAULT '',
  `doi_cong` VARCHAR(40) NOT NULL DEFAULT '',
  `doi_thu` VARCHAR(40) NOT NULL DEFAULT '',
  `suc_cong` INT NOT NULL DEFAULT 0,
  `suc_thu` INT NOT NULL DEFAULT 0,
  `thu_hinh` VARCHAR(64) NOT NULL DEFAULT '',
  `sua_luc` DATETIME NOT NULL,
  PRIMARY KEY (`id_char`),
  KEY `idx_dtd_suc` (`suc_thu`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `tob_dau_truong_mua` (
  `mua` INT NOT NULL,
  `id_char` INT NOT NULL,
  `diem` INT NOT NULL DEFAULT 1000,
  `thang` INT NOT NULL DEFAULT 0,
  `thua` INT NOT NULL DEFAULT 0,
  `thu_thang` INT NOT NULL DEFAULT 0,
  `thu_thua` INT NOT NULL DEFAULT 0,
  `so_tran` INT NOT NULL DEFAULT 0,
  `cap_nhat` DATETIME NOT NULL,
  PRIMARY KEY (`mua`, `id_char`),
  KEY `idx_dtm_diem` (`mua`, `diem`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `tob_dau_truong_tran` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `mua` INT NOT NULL,
  `tuan` INT NOT NULL,
  `ngay` INT NOT NULL,
  `cong` INT NOT NULL,
  `thu` INT NOT NULL,
  `hat` BIGINT NOT NULL DEFAULT 0,
  `ket_qua` TINYINT NOT NULL DEFAULT -1 COMMENT '-1 dang danh, 1 ben tan cong thang, 0 thua',
  `diem_cong_truoc` INT NOT NULL DEFAULT 0,
  `diem_cong_sau` INT NOT NULL DEFAULT 0,
  `diem_thu_truoc` INT NOT NULL DEFAULT 0,
  `diem_thu_sau` INT NOT NULL DEFAULT 0,
  `he_so` SMALLINT NOT NULL DEFAULT 0 COMMENT 'phan nghin, giam dan khi gap lai cung doi thu trong 24 gio',
  `luong` SMALLINT NOT NULL DEFAULT 0 COMMENT 'luong khoa da phat (tran 25 / tuan)',
  `luot` SMALLINT NOT NULL DEFAULT 0,
  `hanh_dong` VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'c0..c3 chieu / d0..d2 doi, cung hat = phat lai dung tran',
  `cong_doi` VARCHAR(160) NOT NULL DEFAULT '' COMMENT 'doi tan cong luc danh (dex.shiny.iv.tinh_cach x 3) - xem lai',
  `thu_doi` VARCHAR(160) NOT NULL DEFAULT '' COMMENT 'doi phong thu luc danh - xem lai',
  `ten_thu` VARCHAR(32) NOT NULL DEFAULT '',
  `bat_dau` DATETIME NOT NULL,
  `luc` DATETIME NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dtt_cong_ngay` (`cong`, `ngay`),
  KEY `idx_dtt_cong_tuan` (`cong`, `tuan`),
  KEY `idx_dtt_tuan` (`tuan`),
  KEY `idx_dtt_thu` (`thu`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `tob_dau_truong_thuong` (
  `mua` INT NOT NULL,
  `id_char` INT NOT NULL,
  `hang` INT NOT NULL DEFAULT 0,
  `diem` INT NOT NULL DEFAULT 0,
  `so_tran` INT NOT NULL DEFAULT 0,
  `danh_hieu` INT NOT NULL DEFAULT 0,
  `luc` DATETIME NOT NULL,
  PRIMARY KEY (`mua`, `id_char`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

ON DUPLICATE KEY UPDATE `ma`=VALUES(`ma`), `ten`=VALUES(`ten`), `mo_ta`=VALUES(`mo_ta`), `goi_y`=VALUES(`goi_y`),
  `do_hiem`=VALUES(`do_hiem`), `hinh`=VALUES(`hinh`), `chi_so`=VALUES(`chi_so`), `phan_nghin`=VALUES(`phan_nghin`),
  `dieu_kien`=VALUES(`dieu_kien`), `tham_so`=VALUES(`tham_so`), `so_luong`=VALUES(`so_luong`), `an`=VALUES(`an`),
  `thoi_han_phut`=VALUES(`thoi_han_phut`), `nguon`=VALUES(`nguon`), `thu_tu`=VALUES(`thu_tu`), `bat`=VALUES(`bat`);
