UPDATE `nap_cua_hang` SET `ten` = 'Trang phục Kính râm', `mo_ta` = IF(`mo_ta` = '', 'Kính râm đẩy lên trán và khăn rằn. Chỉ đổi hình: chỉ số theo ô, như món miễn phí.', `mo_ta`) WHERE `ma` = 'skin_kinh_ram' AND `ten` = 'Skin: Kính râm';
UPDATE `nap_cua_hang` SET `ten` = 'Trang phục Nơ xinh', `mo_ta` = IF(`mo_ta` = '', 'Nơ tim trên đầu và nơ cổ. Chỉ đổi hình: chỉ số theo ô, như món miễn phí.', `mo_ta`) WHERE `ma` = 'skin_no_xinh' AND `ten` = 'Skin: Nơ xinh';
UPDATE `nap_cua_hang` SET `ten` = 'Hào quang Lửa thiêng', `mo_ta` = IF(`mo_ta` = '', 'Ngọn lửa thiêng cháy quanh chân. Chỉ đổi hình: chỉ số theo ô, như món miễn phí.', `mo_ta`) WHERE `ma` = 'hao_quang_lua' AND `ten` = 'Hào quang Lửa';
UPDATE `nap_cua_hang` SET `ten` = 'Hào quang Sóng nước', `mo_ta` = IF(`mo_ta` = '', 'Vòng sóng nước dâng quanh chân. Chỉ đổi hình: chỉ số theo ô, như món miễn phí.', `mo_ta`) WHERE `ma` = 'hao_quang_nuoc' AND `ten` = 'Hào quang Nước';
UPDATE `nap_cua_hang` SET `ten` = 'Yên vân mây', `mo_ta` = IF(`mo_ta` = '', 'Yên trắng như mây trời. Chỉ đổi hình: chỉ số theo ô, như món miễn phí.', `mo_ta`) WHERE `ma` = 'thu_cuoi_van_may' AND `ten` = 'Skin thú cưỡi: Vân mây';
UPDATE `nap_cua_hang` SET `ten` = 'Yên cầu vồng nhạt', `mo_ta` = IF(`mo_ta` = '', 'Yên sắc cầu vồng nhạt. Chỉ đổi hình: chỉ số theo ô, như món miễn phí.', `mo_ta`) WHERE `ma` = 'thu_cuoi_cau_vong' AND `ten` = 'Skin thú cưỡi: Cầu vồng';
