-- >>> them_quan_ly_thu.sql
-- ==================================================================================
--  QUAN LY THU: O THU + VE MO O THU + THA VE TU NHIEN + KHOA THU  (real.QuanLyThuGame, com.htbb.pokemon.OThu)
-- ==================================================================================
--
--  Them 23/10/2026. Chay lai bao nhieu lan cung duoc (MariaDB 10.3 / MySQL 5.x, utf8).
--
--  Thu cuoi (tob_animal) + Pokemon di theo (tob_pet) dung CHUNG mot suc chua "O thu":
--  thu.o_co_ban (20) + o da mo bang ve (tob_char.o_thu_mo), toi da thu.o_toi_da (60) - cau_hinh nhom kinh_te.
--  Day o: moi duong nhan thu bi tu choi kem thong bao; nhan vat cu dang vuot giu nguyen (khong xoa).
--  Tha ve tu nhien: xoa thu (tob_pet DELETE / tob_animal del=1 nhu cac duong xoa cu), tra it xu
--  (thu.tha_xu_*; thu co han = 0 xu; tran / ngay thu.tha_xu_ngay 2000 xu, dem o tob_char.thu_xu_ngay + thu_ngay -
--  dang nhap lai / khoi dong lai khong dat lai), ghi nhat ky saveOrtherLog hanh dong THATHU. Khoa thu: tob_char.thu_khoa
--  (pet co ten tra phi tu khoa; "-p<id>" = nguoi choi da mo khoa tay).
--
--  KHONG BAT BUOC CHAY phan cot: may chu TU THEM cot luc khoi dong (Database.themCotQuanLyThu). Hai cot luu bang
--  cau UPDATE rieng (Database.luuCotQuanLyThu) nen thieu cot KHONG khoa nhan vat.
--
--  Mau nguyen lieu "Vé mở ô thú" (id 271, anh 96 -> icon the do) nam trong ma server
--  (real/MapNapTaiNguyen.loadGemTemplate), khong co bang du lieu.
-- ==================================================================================

-- ---------------------------------------------------------------- 1. cot tob_char (idempotent)
ALTER TABLE `tob_char` ADD COLUMN IF NOT EXISTS `o_thu_mo` INT NOT NULL DEFAULT 0 COMMENT 'O thu da mo bang Ve mo o thu (real.QuanLyThuGame)';
ALTER TABLE `tob_char` ADD COLUMN IF NOT EXISTS `thu_khoa` VARCHAR(1024) NOT NULL DEFAULT '' COMMENT 'Thu da khoa: a<id tob_animal>,p<id tob_pet> (real.QuanLyThuGame)';
ALTER TABLE `tob_char` ADD COLUMN IF NOT EXISTS `thu_xu_ngay` INT NOT NULL DEFAULT 0 COMMENT 'Xu tha thu da nhan trong ngay thu_ngay (tran thu.tha_xu_ngay)';
ALTER TABLE `tob_char` ADD COLUMN IF NOT EXISTS `thu_ngay` INT NOT NULL DEFAULT 0 COMMENT 'Ngay (yyyymmdd) cua thu_xu_ngay';

