UPDATE `data_noi_dung_cua_hang` c JOIN `data_item` i ON c.`vat_pham` = CONCAT('item:', i.`id`) SET c.`ten` = i.`name` WHERE i.`type` <= 11 AND i.`level` > 0 AND i.`name` = CONCAT(c.`ten`, ' · Cấp ', i.`level`);
UPDATE `data_noi_dung_roi` c JOIN `data_item` i ON c.`vat_pham` = CONCAT('item:', i.`id`) SET c.`ten` = i.`name` WHERE i.`type` <= 11 AND i.`level` > 0 AND i.`name` = CONCAT(c.`ten`, ' · Cấp ', i.`level`);
UPDATE `data_noi_dung_che_tao` c JOIN `data_item` i ON c.`thanh_pham` = CONCAT('item:', i.`id`) SET c.`ten` = i.`name` WHERE i.`type` <= 11 AND i.`level` > 0 AND i.`name` = CONCAT(c.`ten`, ' · Cấp ', i.`level`);
UPDATE `data_noi_dung_trang_bi` c JOIN `data_item` i ON c.`id_item` = i.`id` SET c.`ten` = i.`name` WHERE i.`type` <= 11 AND i.`level` > 0 AND i.`name` = CONCAT(c.`ten`, ' · Cấp ', i.`level`);

-- >>> loc_tu_cam_ca_tu.sql
-- ==================================================================================
--  LOC TU CAM THEO CA TU (0.9.14, bao cao QA #7). Chay lai bao nhieu lan cung duoc.
--  Server (com.htbb.pokemon.LocTuCam): tu <= 3 chu co nguyen am chi chan / che CA TU ("ngu" khong chan "Nguyenvu");
--  tu dai va cum phu am ("dkm", "vcl") van chuoi con. Cot kieu: '' = tu dong, 'tu' = ca tu, 'chuoi' = chuoi con.
--  Bo cac dong KHONG tuc tiu khoi danh sach (chan ten that Phongvu, Tayson, Shadow / Gyarados / Kadabra "ad"...).
-- ==================================================================================
ALTER TABLE `bad_word` ADD COLUMN IF NOT EXISTS `kieu` VARCHAR(8) NOT NULL DEFAULT '' COMMENT 'tu = ca tu, chuoi = chuoi con, rong = tu dong (<= 3 chu co nguyen am: ca tu)';
DELETE FROM `bad_word` WHERE `word` IN ('phong','tay','ad','lau','chay','chai','vat','game','test','sv','vv','suc');

-- >>> doi_icon_trang_bi.sql
-- ==================================================================================
--  ICON MON GOC TRANG BI (them 24/10/2026, chu game: "icon sai" o Kho do). Chay lai bao nhieu lan cung duoc (UPDATE
--  theo o + icon CU + danh tu dau ten: admin da doi icon thi giu; lan chay sau icon da moi -> khong khop).
--  Mon goc moi o (sơ cấp..tối thượng, 34..64 mau / o) dung chung icon PMD 14000+type - 9 o nhin sai do vat: Đai (soi day
--  xoan), Băng đô (tui nau), Than lửa (khoi gach), Khăn lụa (cuc da), Nam châm (vien bi sat), Huy hiệu (bia tron),
--  Vòng cổ (hat ngoc), Lông vũ (vay ca tron), Găng đấm (mong vuot). Nay dung icon tu ve cua bo do ho / vung CUNG o
--  (map/icon_do_moi, id 15000+n, da co PNG): mau "Meowth" (he Thuong) cho o ho, mau thanh pho hop do vat cho o vung.
--  Giu: Khăn quàng 14000, Hạt giống thần 14004, Nước thần 14006, Phiến đá 14012, Ruy băng 14013 (da dung hinh).
--  Bang ma: server/src/com/htbb/pokemon/IconTrangBi.java. Kiem: server/test/KiemIconTrangBi.java.
--  Do thoi trang / mat na / skin trong cung o (ten khong bat dau bang danh tu cua o) KHONG doi: xem bao cao.
-- ==================================================================================
