INSERT INTO `data_huong_dan_tan_thu` VALUES ('bo_qua.da_xong',22,'','Bạn đã xong hướng dẫn tân thủ.','',NULL),('bo_qua.hoi',20,'','Bỏ qua hướng dẫn tân thủ? Bạn vẫn nhận đủ thưởng của các bước còn lại: {thuong}. Không làm lại được.','',NULL),('bo_qua.tui_day',23,'','Hành trang không đủ chỗ cho phần thưởng. Hãy dọn bớt vài ô rồi thử lại.','',NULL),('bo_qua.xong',21,'','Đã bỏ qua hướng dẫn. Đã nhận: {thuong}. Gặp Trưởng làng Xatu để bắt đầu cốt truyện.','',NULL),('moi.bat_dau',5,'','Hãy gặp Trưởng làng Xatu, NPC có dấu nhiệm vụ trên đầu.','',NULL),('moi.bo_qua',4,'Bỏ qua hướng dẫn (đã quen chơi)','Bỏ qua hướng dẫn (đã quen chơi)','',NULL),('moi.chao',1,'','Chào mừng tới làng! Đi theo dấu nhiệm vụ trên đầu NPC và chấm trên bản đồ nhỏ.','',NULL),('moi.chao_phu',2,'','Mở Nhiệm vụ, chọn nhiệm vụ rồi bấm Đi tới để tự tìm đường.','',NULL),('moi.lam',3,'Làm hướng dẫn tân thủ (khuyên dùng)','Làm hướng dẫn tân thủ (khuyên dùng)','',NULL),('npc.01_xatu',30,'Xatu · trưởng làng','Trưởng làng Xatu: giao nhiệm vụ cốt truyện chính. Có mặt ở cả ba làng Pewter, Blackthorn, Cianwood.','',NULL),('npc.02_chansey',31,'Chansey · hồi phục','Y tá Chansey đứng trước cửa Trung tâm Pokémon: hồi đầy HP và PP miễn phí, bán thuốc hồi phục và Poké Ball. Chansey tặng bạn 5 Poké Ball: gặp Pokémon HOANG DÃ (dấu Poké Ball cạnh tên), đánh còn ≤ 35% HP rồi bấm nút Poké Ball để thu phục.','',NULL),('npc.03_kecleon',32,'Kecleon · tạp hoá','Kecleon tạp hoá: bán Thuốc hồi máu, Ether và đồ dùng hằng ngày. Chạm vào rồi chọn Mua.','',NULL),('npc.04_blaziken',33,'Blaziken · huấn luyện','Huấn luyện viên Blaziken: dạy chiêu mới (trả xu). Điểm kỹ năng nhận khi lên cấp: Menu → Pokémon → Kỹ năng → Học.','',NULL),('npc.05_machamp',34,'Machamp · thợ rèn','Machamp thợ rèn: nâng cấp, khảm ngọc, sửa và chế tạo trang bị.','',NULL),('npc.06_bronzong',35,'Bronzong · bán giáp','Bronzong thợ giáp: bán trang bị phòng thủ theo hệ và cấp.','',NULL),('npc.07_persian',36,'Persian · đá quý','Ngài Persian: bán đá quý và nguyên liệu nâng cấp.','',NULL),('npc.08_meowth',37,'Meowth · ngân hàng','Meowth thương nhân: ngân hàng, gửi và rút xu, lượng; chuyển lượng cho Pokémon khác.','',NULL),('npc.09_kangaskhan',38,'Kangaskhan · giữ đồ','Kangaskhan thủ kho: giữ bớt đồ khi hành trang đầy.','',NULL),('npc.10_pidgeot',39,'Pidgeot · chở bay','Pidgeot: chở bay tới các vùng xa, trả bằng xu. Vùng mới mở dần theo cấp.','',NULL),('npc.11_snorlax',40,'Snorlax · cốt truyện','Ông Snorlax: giao nhiệm vụ cốt truyện chương đầu, ngay trong làng.','',NULL),('npc.12_doi_thuong',41,'Đổi thưởng · Sổ tay','NPC Đổi thưởng: đổi điểm lấy vật phẩm; mở Pokédex, Sổ tay huấn luyện (nhiệm vụ ngày, tuần, thách đấu Gym) và Hệ sinh thái.','',NULL),('npc.13_tong_quan',42,'Tổng quản · quà tặng','Tổng quản: nhận quà Giftcode, mở rộng hành trang, chuyển vùng. Mã quà cũng nhập được ở Menu → Thư/Quà.','',NULL),('npc.14_cau_ca',43,'Câu cá ở ao làng','Đứng sát mép ao trong làng, mở Menu → Hệ sinh thái → Câu cá. Mỗi lần câu tốn thể lực sinh hoạt và ít xu mua mồi.','',NULL),('npc.15_tu_dong',44,'Tự động đánh','Nút Tự động trên màn hình: Pokémon tự đánh quái gần nhất và tự dùng thuốc theo ngưỡng. Chỉ dùng ở bản đồ có Pokémon hoang dã.','',NULL),('npc.16_pokedex',45,'Pokédex','Menu → Pokédex: ghi mọi loài đã gặp và đã hạ; xong một vùng có thưởng.','',NULL),('npc.17_thu',46,'Thư và quà','Menu → Thư/Quà: hộp thư và ô nhập mã quà tặng.','',NULL),('so_tay.bo_qua',10,'Bỏ qua hướng dẫn tân thủ','Bỏ qua hướng dẫn tân thủ','',NULL),('so_tay.huong_dan',11,'Hướng dẫn tân thủ: công dụng các NPC','Hướng dẫn tân thủ: công dụng các NPC','',NULL);
