INSERT INTO `data_loai` VALUES (1,'Bulbasaur','bulbasaur',1,4,7,45,49,49,65,65,45,318,0,1,1,0,1,4,60,1,0,1,7,'dong_co',1,7,69,1,1,'Hạt giống lớn trên lưng Bulbasaur hấp thu ánh nắng để nuôi cơ thể nhỏ bé hệ Cỏ và Độc. Sống ở đồng cỏ, nó tiến hoá thành Ivysaur khi đạt cấp 16.',NULL),(2,'Ivysaur','ivysaur',1,4,7,60,62,63,80,80,60,405,0,1,1,1,2,4,60,1,0,1,7,'dong_co',1,10,130,1,1,'Nụ hoa trên lưng Ivysaur ngày càng nặng, buộc đôi chân sau phải khoẻ lên để đỡ. Khi nụ sắp nở, nó tiến hoá thành Venusaur ở cấp 32.',NULL),(3,'Venusaur','venusaur',1,4,7,80,82,83,100,100,80,525,0,1,1,2,3,4,60,1,0,1,7,'dong_co',1,20,1000,1,1,'Đóa hoa khổng lồ xòe rộng trên lưng Venusaur cần nhiều nắng và tỏa hương dịu khắp đồng cỏ. Thân hình nặng chừng 100 kg khiến nó di chuyển chậm nhưng vững chãi.',NULL),(4,'Charmander','charmander',1,1,-1,39,52,43,60,50,65,309,0,2,4,0,1,4,60,1,0,1,14,'nui',1,6,85,1,1,'Ngọn lửa ở chóp đuôi cho biết sức khoẻ của Charmander, lửa yếu dần khi nó mệt. Chú thằn lằn nhỏ hệ Lửa này sống vùng núi và tiến hoá thành Charmeleon ở cấp 16.',NULL),(5,'Charmeleon','charmeleon',1,1,-1,58,64,58,80,65,80,405,0,2,4,4,2,4,60,1,0,1,14,'nui',1,11,190,1,1,'Móng vuốt sắc và tính khí nóng nảy khiến Charmeleon hay tìm đối thủ để thử sức giữa vùng núi đá. Đạt cấp 36, nó tiến hoá thành Charizard.',NULL),(6,'Charizard','charizard',1,1,9,78,84,78,109,85,100,534,0,2,4,5,3,4,60,1,0,1,14,'nui',1,17,905,1,1,'Đôi cánh rộng giúp Charizard bay cao trên các đỉnh núi, phun lửa nóng đủ làm chảy đá. Mang hệ Lửa và Bay, nó chỉ đấu hết sức với đối thủ xứng tầm.',NULL),(7,'Squirtle','squirtle',1,2,-1,44,48,65,50,64,43,314,0,3,7,0,1,4,60,1,0,1,2,'ven_nuoc',1,5,90,1,1,'Mai tròn vừa che chắn vừa giúp Squirtle lướt nhanh dưới nước rồi phun tia nước mạnh. Sống ven nước, chú rùa nhỏ này tiến hoá thành Wartortle ở cấp 16.',NULL),(8,'Wartortle','wartortle',1,2,-1,59,63,80,65,80,58,405,0,3,7,7,2,4,60,1,0,1,2,'ven_nuoc',1,10,225,1,1,'Đôi tai và chiếc đuôi phủ lông mềm giúp Wartortle giữ thăng bằng khi bơi. Đuôi càng dày thì tuổi càng cao; nó tiến hoá thành Blastoise khi đạt cấp 36.',NULL),(9,'Blastoise','blastoise',1,2,-1,79,83,100,85,105,78,530,0,3,7,8,3,4,60,1,0,1,2,'ven_nuoc',1,16,855,1,1,'Hai khẩu pháo nước nhô ra từ mai cho phép Blastoise bắn những luồng nước cực mạnh. Nặng hơn 85 kg, nó dùng sức nặng để ghìm chặt người khi khai hỏa.',NULL),(10,'Caterpie','caterpie',1,11,-1,45,30,35,20,20,45,195,0,4,10,0,1,1,400,1,0,3,NULL,'rung',4,3,29,1,1,'Chiếc râu đỏ trên đầu Caterpie tỏa mùi hăng để xua kẻ săn mồi. Sâu non hệ Bọ này ăn lá rừng không ngừng và hóa nhộng thành Metapod ở cấp 7.',NULL),(11,'Metapod','metapod',1,11,-1,50,20,55,25,25,30,205,0,4,10,10,2,2,250,1,0,3,NULL,'rung',4,7,99,1,1,'Lớp vỏ nhộng cứng như thép bảo vệ phần thân mềm đang biến đổi bên trong Metapod. Nó gần như bất động trên cành cây cho tới khi tiến hoá thành Butterfree ở cấp 10.',NULL),(12,'Butterfree','butterfree',1,11,9,60,45,50,90,80,70,395,0,4,10,11,3,3,120,1,0,3,NULL,'rung',4,11,320,1,1,'Vảy phấn trên đôi cánh Butterfree có thể gây ngủ hoặc tê liệt kẻ thù. Bướm hệ Bọ và Bay này lượn khắp rừng để tìm mật hoa.',NULL),(13,'Weedle','weedle',1,11,7,40,35,30,20,20,50,195,0,5,13,0,1,1,400,1,0,3,NULL,'rung',4,3,32,1,1,'Chiếc gai độc trên đầu Weedle dài khoảng vài phân, đủ làm kẻ thù đau điếng. Sâu nhỏ này sống trong rừng, ăn lá và tiến hoá thành Kakuna ở cấp 7.',NULL),(14,'Kakuna','kakuna',1,11,7,45,25,50,25,25,35,205,0,5,13,13,2,2,250,1,0,3,NULL,'rung',4,6,100,1,1,'Bên trong lớp kén vàng, Kakuna lặng lẽ chuẩn bị cho lần biến đổi sắp tới. Tuy ít cử động, nó vẫn có thể chĩa gai độc khi bị quấy rầy, rồi tiến hoá thành Beedrill ở cấp 10.',NULL),(15,'Beedrill','beedrill',1,11,7,65,90,40,45,80,75,395,0,5,13,14,3,3,120,1,0,3,NULL,'rung',4,10,295,1,1,'Hai chi trước và đuôi của Beedrill đều mang ngòi độc nhọn. Loài ong hệ Bọ và Độc này sống theo đàn trong rừng và tấn công dồn dập khi tổ bị xâm phạm.',NULL),(16,'Pidgey','pidgey',1,0,9,40,45,40,35,35,56,251,0,6,16,0,1,1,400,1,0,4,NULL,'rung',4,3,18,1,1,'Pidgey hiền lành, thường kiếm ăn trên mặt đất và quạt cánh tạo cát bụi để tự vệ. Chim nhỏ hệ Thường và Bay này tiến hoá thành Pidgeotto ở cấp 18.',NULL),(17,'Pidgeotto','pidgeotto',1,0,9,63,60,55,50,50,71,349,0,6,16,16,2,2,250,1,0,4,NULL,'rung',4,11,300,1,1,'Với móng vuốt khoẻ, Pidgeotto tuần tra rộng khắp khu rừng nơi nó sinh sống và lao xuống bắt mồi rất chuẩn. Ở cấp 36, nó tiến hoá thành Pidgeot.',NULL),(18,'Pidgeot','pidgeot',1,0,9,83,80,75,70,70,101,479,0,6,16,17,3,3,120,1,0,4,NULL,'rung',4,15,395,1,1,'Bộ lông mào óng ả và đôi cánh mạnh mẽ giúp Pidgeot bay vút trên tán rừng với tốc độ rất cao. Nó có thể tạo ra những cơn gió đủ làm cây lớn nghiêng ngả.',NULL),(19,'Rattata','rattata',1,0,-1,30,56,35,25,35,72,253,0,7,19,0,1,1,400,1,0,5,NULL,'dong_co',4,3,35,1,1,'Hàm răng cửa không ngừng mọc buộc Rattata phải gặm nhấm liên tục. Loài gặm nhấm nhanh nhẹn này có mặt khắp đồng cỏ và tiến hoá thành Raticate ở cấp 20.',NULL),(20,'Raticate','raticate',1,0,-1,55,81,60,50,70,97,413,0,7,19,19,2,2,250,1,0,5,NULL,'dong_co',4,7,185,1,1,'Raticate dùng những chiếc ria dài để giữ thăng bằng và cặp răng cửa chắc khỏe để gặm cả gỗ cứng. Chân sau có màng nhỏ giúp nó bơi qua dòng nước.',NULL),(21,'Spearow','spearow',1,0,9,40,60,30,31,31,70,262,0,8,21,0,1,1,400,1,0,4,NULL,'go_ghe',4,3,20,1,1,'Dù cánh ngắn, Spearow vỗ cánh rất nhanh và kêu inh ỏi để báo động cả đàn. Chim nhỏ này sống ở vùng địa hình gồ ghề và tiến hoá thành Fearow ở cấp 20.',NULL),(22,'Fearow','fearow',1,0,9,65,90,65,61,61,100,442,0,8,21,21,2,2,250,1,0,4,NULL,'go_ghe',4,12,380,1,1,'Chiếc mỏ dài và đôi cánh lớn cho phép Fearow bay liên tục suốt cả ngày mà không cần đậu. Nó mổ con mồi dưới đất hoặc dưới nước bằng mỏ nhọn hoắt.',NULL),(23,'Ekans','ekans',1,7,-1,35,60,44,40,54,55,288,0,9,23,0,1,1,400,1,0,5,14,'dong_co',4,20,69,1,1,'Ekans quấn mình nằm chờ trên cỏ, lặng lẽ nuốt trọn trứng chim hoặc mồi nhỏ. Rắn hệ Độc này dài khoảng 2 m và tiến hoá thành Arbok ở cấp 22.',NULL),(24,'Arbok','arbok',1,7,-1,60,95,69,65,79,80,448,0,9,23,23,2,2,250,1,0,5,14,'dong_co',4,35,650,1,1,'Hoa văn trên phần cổ phình của Arbok trông như một khuôn mặt dữ tợn để dọa kẻ thù. Dài tới 3,5 m, nó siết con mồi rất chặt trước khi cắn.',NULL),(25,'Pikachu','pikachu',1,3,-1,35,55,40,50,50,90,320,0,10,172,172,1,1,400,1,0,5,6,'rung',4,4,60,1,1,'Hai túi má đỏ của Pikachu tích điện và phóng ra khi nó cảm thấy bị đe dọa. Loài hệ Điện này sống thành nhóm trong rừng và tiến hoá thành Raichu khi dùng Đá Sấm.',NULL),(26,'Raichu','raichu',1,3,-1,60,90,55,90,80,110,485,0,10,172,25,2,2,250,1,0,5,6,'rung',4,8,300,1,1,'Chiếc đuôi dài của Raichu có thể cắm xuống đất để xả bớt điện dư thừa. Khi tích quá nhiều điện, nó trở nên hung hăng và cơ thể phát sáng mờ trong bóng tối.',NULL),(27,'Sandshrew','sandshrew',1,8,-1,50,75,85,20,30,40,300,0,11,27,0,1,1,400,1,0,5,NULL,'go_ghe',4,6,120,1,1,'Sandshrew cuộn tròn thành một quả bóng có lớp da khô cứng để tránh đòn. Sống ở địa hình gồ ghề khô cằn, nó đào hang rất giỏi và tiến hoá thành Sandslash ở cấp 22.',NULL),(28,'Sandslash','sandslash',1,8,-1,75,100,110,45,55,65,450,0,11,27,27,2,2,250,1,0,5,NULL,'go_ghe',4,10,295,1,1,'Lưng Sandslash phủ đầy gai sắc hình thành từ lớp da cứng lại. Khi gặp nguy, nó cuộn tròn để gai dựng đứng, rồi dùng móng vuốt đào hang lẩn trốn.',NULL),(29,'Nidoran♀','nidoran-f',1,7,-1,55,47,52,40,40,41,275,0,12,29,0,1,1,400,1,0,1,5,'dong_co',8,4,70,1,1,'Nidoran♀ nhỏ nhắn nhưng ngòi gai trên người chứa độc mạnh. Nó sống ở đồng cỏ, thường tránh giao tranh và tiến hoá thành Nidorina ở cấp 16.',NULL),(30,'Nidorina','nidorina',1,7,-1,70,62,67,55,55,56,365,0,12,29,29,2,2,250,1,0,15,NULL,'dong_co',8,8,200,1,1,'Tính tình điềm đạm, Nidorina thu gai lại khi ở cạnh đồng loại thân quen. Khi được dùng Đá Mặt Trăng, nó tiến hoá thành Nidoqueen.',NULL),(31,'Nidoqueen','nidoqueen',1,7,8,90,92,87,75,85,76,505,0,12,29,30,3,3,120,1,0,15,NULL,'dong_co',8,13,600,1,1,'Lớp vảy cứng như giáp bọc quanh thân hình chắc nịch của Nidoqueen. Mang hệ Độc và Đất, nó dùng sức nặng 60 kg để húc ngã đối thủ, đồ