L),(147,'Dratini','dratini',1,14,-1,41,64,45,50,50,50,300,0,76,147,0,1,4,60,1,0,2,14,'ven_nuoc',4,18,33,1,1,'Dratini hệ Rồng có thân dài mảnh như rắn, nhẵn bóng, thường ẩn mình nơi vùng nước sâu yên tĩnh. Nó lột da nhiều lần khi lớn lên và tiến hoá thành Dragonair ở cấp 30.',NULL),(148,'Dragonair','dragonair',1,14,-1,61,84,65,70,70,70,420,0,76,147,147,2,4,60,1,0,2,14,'ven_nuoc',4,40,165,1,1,'Viên ngọc trên cổ và đuôi Dragonair được cho là giúp nó tác động lên thời tiết quanh mình. Pokémon hệ Rồng dài khoảng bốn mét này sẽ thành Dragonite khi đạt cấp 55.',NULL),(149,'Dragonite','dragonite',1,14,9,91,134,95,100,100,80,600,0,76,147,148,3,5,25,1,1,2,14,'ven_nuoc',4,22,2100,1,1,'Dragonite hệ Rồng và Bay nặng khoảng 210 kg nhưng vẫn bay khoẻ nhờ đôi cánh nhỏ trên lưng. Đây là dạng cuối của Dratini, nổi tiếng hiền lành và hay cứu giúp người đi biển.',NULL),(150,'Mewtwo','mewtwo',1,10,-1,106,110,90,154,90,130,680,1,77,150,0,1,6,30,0,1,15,NULL,'hiem',-1,20,1220,1,1,'Mewtwo là Pokémon hệ Siêu linh huyền thoại được tạo ra từ thí nghiệm di truyền, sở hữu sức mạnh tâm linh khổng lồ. Nó lạnh lùng, cảnh giác và tránh xa con người.',NULL),(151,'Mew','mew',1,10,-1,100,100,100,100,100,100,600,2,78,151,0,1,6,30,0,1,15,NULL,'hiem',-1,4,40,1,1,'Mew là Pokémon huyền ảo hệ Siêu linh, nhỏ chỉ 0.4 m, được cho là mang gen của mọi loài Pokémon. Nó có thể tàng hình và hiếm khi chịu xuất hiện trước người lạ.',NULL),(152,'Chikorita','chikorita',2,4,-1,45,49,65,49,65,45,318,0,79,152,0,1,4,60,1,0,1,7,'dong_co',1,9,64,1,1,'Chiếc lá lớn trên đầu Chikorita toả mùi thơm dịu và được nó dùng để cảm nhận nhiệt độ, độ ẩm. Pokémon hệ Cỏ này thích phơi nắng trên đồng cỏ, lên cấp 16 thành Bayleef.',NULL),(153,'Bayleef','bayleef',2,4,-1,60,62,80,63,80,60,405,0,79,152,152,2,4,60,1,0,1,7,'dong_co',1,12,158,1,1,'Quanh cổ Bayleef là một vòng nụ lá cuộn tròn, toả hương cay nhẹ khiến người ngửi thấy thêm hăng hái. Nó thuộc hệ Cỏ, tiến hoá từ Chikorita và thành Meganium ở cấp 32.',NULL),(154,'Meganium','meganium',2,