INSERT INTO `data_noi_dung_nguyen_lieu` VALUES ('bua_bao_ho','Bùa bảo hộ','bua','ngoc:0/1/2','Giữ cấp khi nâng cấp +7 đến +10 thất bại','cửa hàng lượng khoá',10,'luong_khoa'),('bua_bao_ho_cao','Bùa bảo hộ cao cấp','bua','ngoc:3/4','Giữ cấp khi nâng cấp +11 đến +15 thất bại','cửa hàng lượng khoá',25,'luong_khoa'),('bui_sao','Bụi sao','nguyen_lieu_phu','item:1034','Nâng cấp +11 đến +15 cho đồ bậc sơ cấp, đồng, bạc (1 cái mỗi lần thử)','quái ở dải cấp của bậc rơi (0,4%), phân rã đồ bậc đó, chế tạo',0,'khong_ban'),('da_nang_cap','Đá nâng cấp','nguyen_lieu_chinh','ngoc:8','Mọi lần nâng cấp: lên +1 đến +5 cần 1 viên, +6 đến +10 cần 2 viên, +11 đến +15 cần 4 viên','quái chênh tối đa 5 cấp rơi 1,5%, quái tinh anh chắc chắn rơi, phân rã 1 món được 2 viên',0,'khong_ban'),('manh_sao','Mảnh sao','nguyen_lieu_phu','item:1035','Nâng cấp +11 đến +15 cho đồ bậc vàng, bạch kim, kim cương (1 cái mỗi lần thử)','quái ở dải cấp của bậc rơi (0,4%), phân rã đồ bậc đó, chế tạo',0,'khong_ban'),('manh_thien_thach','Mảnh thiên thạch','nguyen_lieu_phu','item:1036','Nâng cấp +11 đến +15 cho đồ bậc chuyên gia, tinh anh, huyền thoại (1 cái mỗi lần thử)','quái ở dải cấp của bậc rơi (0,4%), phân rã đồ bậc đó, chế tạo',0,'khong_ban'),('manh_tinh_hoa','Mảnh tinh hoa','nguyen_lieu_hoan_my','item:1038','Chuyển đồ Hoàn mỹ sang bậc mới (cần 3 mảnh)','phân rã đồ Hoàn mỹ',0,'khong_ban'),('vay_rong','Vảy rồng','nguyen_lieu_phu','item:1037','Nâng cấp +11 đến +15 cho đồ bậc thần thoại, tối thượng (1 cái mỗi lần thử)','quái ở dải cấp của bậc rơi (0,4%), phân rã đồ bậc đó, chế tạo',0,'khong_ban');
