INSERT INTO `data_trang_bi_ho` VALUES ('he_bang_tinh','Bộ Băng Tinh','he',5,1,'',2,10,'Bộ Băng Tinh: đồ hệ Băng (Snorunt → Regice). 2 món +2% sát thương hệ Băng, 4 món +3% kháng hệ Lửa, 6 món thêm +3% sát thương hệ Băng.',6,1),('he_binh_nguyen','Bộ Bình Nguyên','he',0,6,'',2,10,'Bộ Bình Nguyên: đồ hệ Thường (Meowth → Regigigas). 2 món +2% sát thương hệ Thường, 4 món +3% kháng hệ Giác đấu, 6 món thêm +3% sát thương hệ Thường.',1,1),('he_cuong_thiet','Bộ Cương Thiết','he',16,1,'',2,10,'Bộ Cương Thiết: đồ hệ Thép (Magnemite → Dialga). 2 món +2% sát thương hệ Thép, 4 món +3% kháng hệ Lửa, 6 món thêm +3% sát thương hệ Thép.',17,1),('he_dia_chan','Bộ Địa Chấn','he',8,2,'',2,10,'Bộ Địa Chấn: đồ hệ Đất (Sandshrew → Groudon). 2 món +2% sát thương hệ Đất, 4 món +3% kháng hệ Nước, 6 món thêm +3% sát thương hệ Đất.',9,1),('he_diep_luc','Bộ Diệp Lục','he',4,1,'',2,10,'Bộ Diệp Lục: đồ hệ Cỏ (Oddish → Shaymin). 2 món +2% sát thương hệ Cỏ, 4 món +3% kháng hệ Lửa, 6 món thêm +3% sát thương hệ Cỏ.',5,1),('he_doc_duoc','Bộ Độc Dược','he',7,8,'',2,10,'Bộ Độc Dược: đồ hệ Độc (Ekans → Crobat). 2 món +2% sát thương hệ Độc, 4 món +3% kháng hệ Đất, 6 món thêm +3% sát thương hệ Độc.',8,1),('he_giap_trung','Bộ Giáp Trùng','he',11,1,'',2,10,'Bộ Giáp Trùng: đồ hệ Bọ (Caterpie → Heracross). 2 món +2% sát thương hệ Bọ, 4 món +3% kháng hệ Lửa, 6 món thêm +3% sát thương hệ Bọ.',12,1),('he_hac_am','Bộ Hắc Ám','he',15,6,'',2,10,'Bộ Hắc Ám: đồ hệ Bóng tối (Murkrow → Darkrai). 2 món +2% sát thương hệ Bóng tối, 4 món +3% kháng hệ Giác đấu, 6 món thêm +3% sát thương hệ Bóng tối.',16,1),('he_hoa_diem','Bộ Hoả Diệm','he',1,2,'',2,10,'Bộ Hoả Diệm: đồ hệ Lửa (Vulpix → Ho-Oh). 2 món +2% sát thương hệ Lửa, 4 món +3% kháng hệ Nước, 6 món thêm +3% sát thương hệ Lửa.',2,1),('he_loi_quang','Bộ Lôi Quang','he',3,8,'',2,10,'Bộ Lôi Quang: đồ hệ Điện (Pikachu → Raikou). 2 món +2% sát thương hệ Điện, 4 món +3% kháng hệ Đất, 6 món thêm +3% sát thương hệ Điện.',4,1),('he_long_vuong','Bộ Long Vương','he',14,5,'',2,10,'Bộ Long Vương: đồ hệ Rồng (Dratini → Rayquaza). 2 món +2% sát thương hệ Rồng, 4 món +3% kháng hệ Băng, 6 món thêm +3% sát thương hệ Rồng.',15,1),('he_nham_thach','Bộ Nham Thạch','he',12,2,'',2,10,'Bộ Nham Thạch: đồ hệ Đá (Geodude → Regirock). 2 món +2% sát thương hệ Đá, 4 món +3% kháng hệ Nước, 6 món thêm +3% sát thương hệ Đá.',13,1),('he_phong_vu','Bộ Phong Vũ','he',9,3,'',2,10,'Bộ Phong Vũ: đồ hệ Bay (Pidgey → Lugia). 2 món +2% sát thương hệ Bay, 4 món +3% kháng hệ Điện, 6 món thêm +3% sát thương hệ Bay.',10,1),('he_tam_linh','Bộ Tâm Linh','he',10,15,'',2,10,'Bộ Tâm Linh: đồ hệ Siêu linh (Abra → Mewtwo). 2 món +2% sát thương hệ Siêu linh, 4 món +3% kháng hệ Bóng tối, 6 món thêm +3% sát thương hệ Siêu linh.',11,1),('he_thuy_trieu','Bộ Thuỷ Triều','he',2,3,'',2,10,'Bộ Thuỷ Triều: đồ hệ Nước (Staryu → Kyogre). 2 món +2% sát thương hệ Nước, 4 món +3% kháng hệ Điện, 6 món thêm +3% sát thương hệ Nước.',3,1),('he_tien_tu','Bộ Tiên Tử','he',17,16,'',2,10,'Bộ Tiên Tử: đồ hệ Tiên (Cleffa → Xerneas). 2 món +2% sát thương hệ Tiên, 4 món +3% kháng hệ Thép, 6 món thêm +3% sát thương hệ Tiên.',18,1),('he_u_linh','Bộ U Linh','he',13,15,'',2,10,'Bộ U Linh: đồ hệ Ma (Gastly → Giratina). 2 món +2% sát thương hệ Ma, 4 món +3% kháng hệ Bóng tối, 6 món thêm +3% sát thương hệ Ma.',14,1),('he_vo_dao','Bộ Võ Đạo','he',6,10,'',2,10,'Bộ Võ Đạo: đồ hệ Giác đấu (Machop → Terrakion). 2 món +2% sát thương hệ Giác đấu, 4 món +3% kháng hệ Siêu linh, 6 món thêm +3% sát thương hệ Giác đấu.',7,1),('vung_hoenn','Bộ Huy chương Hoenn','vung',-1,-1,'hoenn',8,10,'Bộ Huy chương Hoenn: huy hiệu, găng, phiến đá, đồ cầm tay bậc huyền thoại-tối thượng. 2 món +1% HP, 3 món +1% tấn công, 4 món +1% chí mạng (chung trần bộ 5% / chí mạng bộ 3%).',102,1),('vung_johto','Bộ Huy chương Johto','vung',-1,-1,'johto',4,7,'Bộ Huy chương Johto: huy hiệu, găng, phiến đá, đồ cầm tay bậc bạch kim-tinh anh. 2 món +1% HP, 3 món +1% tấn công, 4 món +1% chí mạng (chung trần bộ 5% / chí mạng bộ 3%).',101,1),('vung_kanto','Bộ Huy chương Kanto','vung',-1,-1,'kanto',0,3,'Bộ Huy chương Kanto: huy hiệu, găng, phiến đá, đồ cầm tay bậc sơ cấp-vàng. 2 món +1% HP, 3 món +1% tấn công, 4 món +1% chí mạng (chung trần bộ 5% / chí mạng bộ 3%).',100,1);
