INSERT INTO `nap_goi` VALUES ('L100','1.000 lượng','luong',100000,1000,'Tỷ giá cố định 10 lượng / 1.000 đ.',1,3,NULL,''),('L20','200 lượng','luong',20000,200,'Tỷ giá cố định 10 lượng / 1.000 đ.',1,1,NULL,''),('L200','2.000 lượng','luong',200000,2000,'Tỷ giá cố định 10 lượng / 1.000 đ.',1,4,NULL,''),('L50','500 lượng','luong',50000,500,'Tỷ giá cố định 10 lượng / 1.000 đ.',1,2,NULL,''),('L500','5.000 lượng','luong',500000,5000,'Tỷ giá cố định 10 lượng / 1.000 đ.',1,5,NULL,''),('THANH_VIEN','Thành viên Huyền Thoại Bảo Bối','thanh_vien',20000,0,'Mở các tính năng cộng đồng (giao dịch, chat thế giới, chợ, đội...) cho MỌI Pokémon của tài khoản. Không tăng sức mạnh.',0,0,NULL,''),('THE_THANG','Thẻ tháng (30 ngày)','the_thang',50000,0,'20 lượng mỗi ngày đăng nhập (30 ngày, bỏ lỡ không cộng bù), +1 lượt Hầm ngục (chỉ điểm vé mùa), +2 ô tự nhặt, +1 trang tủ đồ trang trí, +1 giờ ủy thác luyện tập/ngày (trong giới hạn tăng tốc).',1,6,NULL,''),('VE_MUA','Vé mùa cao cấp','ve_mua',99000,0,'Mở track cao cấp của mùa hiện tại: trang phục, biểu cảm, hào quang; vật liệu khoá đúng bằng track miễn phí. Tiến độ chỉ bằng chơi.',1,7,NULL,'');
