INSERT INTO `bad_word` (`word`) SELECT w.`word` FROM (SELECT 'dume' AS `word` UNION ALL SELECT 'djtme' UNION ALL SELECT 'deome' UNION ALL SELECT 'bucac' UNION ALL SELECT 'pucac' UNION ALL SELECT 'xaolon' UNION ALL SELECT 'laolon' UNION ALL SELECT 'khonnan' UNION ALL SELECT 'sucsinh' UNION ALL SELECT 'nigger' UNION ALL SELECT 'cunt' UNION ALL SELECT 'asshole' UNION ALL SELECT 'bastard') w WHERE NOT EXISTS (SELECT 1 FROM `bad_word` b WHERE b.`word` = w.`word`);
